import heapq

def max_sliding_window(nums, k):
    heap, res = [], []                 # (−value, index)
    for i, x in enumerate(nums):
        heapq.heappush(heap, (-x, i))
        while heap[0][1] <= i - k:
            heapq.heappop(heap)        # lazily drop maxima that left the window
        if i >= k - 1:
            res.append(-heap[0][0])
    return res
